import { UploadError, aborted, fromResponse } from "./errors.js";
/** The upload API of media.UploadHandler; one method per route. */
export class UploadApi {
    o;
    constructor(o) {
        this.o = o;
    }
    presign(b, signal) {
        return this.call("/presign", b, signal);
    }
    parts(b, signal) {
        return this.call("/parts", b, signal);
    }
    listParts(b, signal) {
        return this.call("/parts/list", b, signal);
    }
    complete(b, signal) {
        return this.call("/complete", b, signal);
    }
    abort(b, signal) {
        return this.call("/abort", b, signal);
    }
    commit(b, signal) {
        return this.call("/commit", b, signal);
    }
    commitSlot(b, signal) {
        return this.call("/commit-slot", b, signal);
    }
    async call(path, body, signal) {
        const f = this.o.fetch ?? fetch;
        const headers = new Headers(await this.o.headers?.());
        headers.set("Content-Type", "application/json");
        let res;
        try {
            res = await f(this.o.endpoint.replace(/\/$/, "") + path, {
                method: "POST",
                headers,
                body: JSON.stringify(body),
                credentials: this.o.credentials ?? "same-origin",
                signal: signal ?? null,
            });
        }
        catch (err) {
            if (signal?.aborted)
                throw aborted(signal);
            throw new UploadError("network", `upload API ${path} unreachable`, 0, undefined, { cause: err });
        }
        if (!res.ok)
            throw await fromResponse(res);
        return (res.status === 204 ? undefined : await res.json());
    }
}
